import React, { useState, useEffect, useCallback } from 'react';
import styles from './TerminalCursor.module.css';

// Holographic color spectrum + extended character set
const CHARS = ['0', '1', '$', '#', '@', '&', '%', '>', '<', '/', '\\', '█', '░', '▒', '▓', '◈', '◇', '⦿', '⨀', '⎔', '⌾'];
const COLORS = [
  '#00ffcc', // cyan
  '#00e5ff', // light cyan
  '#4d4dff', // neon blue
  '#b266ff', // purple
  '#ff44cc', // magenta
  '#ff66ff', // pink
];

const TerminalCursor = () => {
  const [particles, setParticles] = useState([]);
  const [isTouchDevice, setIsTouchDevice] = useState(false);

  const addParticle = useCallback((x, y) => {
    const id = Date.now() + Math.random();
    const char = CHARS[Math.floor(Math.random() * CHARS.length)];
    const color = COLORS[Math.floor(Math.random() * COLORS.length)];
    
    setParticles(prev => [...prev, { id, x, y, char, color }]);
    
    setTimeout(() => {
      setParticles(prev => prev.filter(p => p.id !== id));
    }, 1800); // Longer duration for holographic effect
  }, []);

  // Throttle particle generation
  const throttle = useCallback((func, delay) => {
    let lastCall = 0;
    return (...args) => {
      const now = Date.now();
      if (now - lastCall >= delay) {
        lastCall = now;
        func(...args);
      }
    };
  }, []);

  useEffect(() => {
    if ('ontouchstart' in window || navigator.maxTouchPoints > 0) {
      setIsTouchDevice(true);
      return;
    }

    const throttledAddParticle = throttle(addParticle, 40); // ~25 particles per second max

    const handleMouseMove = (e) => {
      throttledAddParticle(e.clientX, e.clientY);
    };

    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, [addParticle, throttle]);

  if (isTouchDevice) return null;

  return (
    <>
      {particles.map(p => (
        <span
          key={p.id}
          className={styles.hologramChar}
          style={{
            left: `${p.x}px`,
            top: `${p.y}px`,
            color: p.color,
            textShadow: `0 0 8px ${p.color}, 0 0 15px ${p.color}, 0 0 25px ${p.color}`,
          }}
        >
          {p.char}
        </span>
      ))}
    </>
  );
};

export default TerminalCursor;
